def kernel(self, float_n: float, data: list, corr: list, mean: list, stddev: list):
        eps = 0.1

        for j in range(0, self.M):
            mean[j] = 0.0
            for i in range(0, self.N):
                mean[j] += data[i][j]
            mean[j] /= float_n

        for j in range(0, self.M):
            stddev[j] = 0.0
            for i in range(0, self.N):
                stddev[j] += (data[i][j] - mean[j]) * (data[i][j] - mean[j])
            stddev[j] /= float_n
            stddev[j] = sqrt(stddev[j])
            # The following in an elegant but usual way to handle near-zero std. dev. values, which below would cause a
            # zero divide.
            stddev[j] = 1.0 if stddev[j] <= eps else stddev[j]

        # Center and reduce the column vectors.
        for i in range(0, self.N):
            for j in range(0, self.M):
                data[i][j] -= mean[j]
                data[i][j] /= sqrt(float_n) * stddev[j]

        # Calculate the m*n correlation matrix.
        for i in range(0, self.M-1):
            corr[i][i] = 1.0
            for j in range(i+1, self.M):
                corr[i][j] = 0.0
                for k in range(0, self.N):
                    corr[i][j] += (data[k][i] * data[k][j])
                corr[j][i] = corr[i][j]
        corr[self.M-1][self.M-1] = 1.0

def kernel(self, float_n: float, data: list, cov: list, mean: list):
        for j in range(0, self.M):
            mean[j] = 0.0
            for i in range(0, self.N):
                mean[j] += data[i][j]
            mean[j] /= float_n

        for i in range(0, self.N):
            for j in range(0, self.M):
                data[i][j] -= mean[j]

        for i in range(0, self.M):
            for j in range(0, self.M):
                cov[i][j] = 0.0
                for k in range(0, self.N):
                    cov[i][j] += data[k][i] * data[k][j]
                cov[i][j] /= float_n - 1.0
                cov[j][i] = cov[i][j]

def kernel(self, alpha: float, beta: float, C: list, A: list, B: list):
        for i in range(0, self.NI):
            for j in range(0, self.NJ):
                C[i][j] *= beta

            for k in range(0, self.NK):
                for j in range(0, self.NJ):
                    C[i][j] += alpha * A[i][k] * B[k][j]

def kernel(self, alpha, beta, A: list, u1: list, v1: list, u2: list, v2: list, w: list, x: list, y: list, z: list):
        for i in range(0, self.N):
            for j in range(0, self.N):
                A[i][j] = A[i][j] + u1[i] * v1[j] + u2[i] * v2[j]

        for i in range(0, self.N):
            for j in range(0, self.N):
                x[i] = x[i] + beta * A[j][i] * y[j]

        for i in range(0, self.N):
            x[i] = x[i] + z[i]

        for i in range(0, self.N):
            for j in range(0, self.N):
                w[i] = w[i] + alpha * A[i][j] * x[j]

def kernel(self, alpha, beta, A: list, B: list, tmp: list, x: list, y: list):
        for i in range(0, self.N):
            tmp[i] = 0.0
            y[i] = 0.0
            for j in range(0, self.N):
                tmp[i] = A[i][j] * x[j] + tmp[i]
                y[i] = B[i][j] * x[j] + y[i]
            y[i] = alpha * tmp[i] + beta * y[i]

def kernel(self, alpha, beta, C: list, A: list, B: list):
        # BLAS PARAMS
        # UPLO  = 'L'
        # TRANS = 'N'
        # A is NxM
        # B is NxM
        # C is NxN
        for i in range(0, self.N):
            for j in range(0, i + 1):
                C[i][j] *= beta

            for k in range(0, self.M):
                for j in range(0, i + 1):
                    C[i][j] += A[j][k]*alpha*B[i][k] + B[j][k]*alpha*A[i][k]

def kernel(self, alpha, beta, C: list, A: list):
        # BLAS PARAMS
        # TRANS = 'N'
        # UPLO  = 'L'
        #  =>  Form  C := alpha*A*A**T + beta*C.
        # A is NxM
        # C is NxN
        for i in range(0, self.N):
            for j in range(0, i + 1):
                C[i][j] *= beta

            for k in range(0, self.M):
                for j in range(0, i + 1):
                    C[i][j] += alpha * A[i][k] * A[j][k]

def kernel(self, alpha, beta, tmp: list, A: list, B: list, C: list, D: list):
        # D := alpha * A * B * C + beta * D
        for i in range(self.NI):
            for j in range(self.NJ):
                tmp[i][j] = 0.0
                for k in range(0, self.NK):
                    tmp[i][j] += alpha * A[i][k] * B[k][j]

        for i in range(0, self.NI):
            for j in range(0, self.NL):
                D[i][j] *= beta
                for k in range(0, self.NJ):
                    D[i][j] += tmp[i][k] * C[k][j]

def kernel(self, E: list, A: list, B: list, F: list, C: list, D: list, G: list):
        # E := A * B
        for i in range(0, self.NI):
            for j in range(0, self.NJ):
                E[i][j] = 0.0
                for k in range(0, self.NK):
                    E[i][j] += A[i][k] * B[k][j]

        # F := C * D
        for i in range(0, self.NJ):
            for j in range(0, self.NL):
                F[i][j] = 0.0
                for k in range(0, self.NM):
                    F[i][j] += C[i][k] * D[k][j]

        # G := E * F
        for i in range(0, self.NI):
            for j in range(0, self.NL):
                G[i][j] = 0.0
                for k in range(0, self.NJ):
                    G[i][j] += E[i][k] * F[k][j]

def kernel(self, A: list, x: list, y: list, tmp: list):
        for i in range(0, self.N):
            y[i] = 0

        for i in range(0, self.M):
            tmp[i] = 0.0
            for j in range(0, self.N):
                tmp[i] = tmp[i] + A[i][j] * x[j]

            for j in range(0, self.N):
                y[j] = y[j] + A[i][j] * tmp[i]

def kernel(self, A: list, s: list, q: list, p: list, r: list):
        for i in range(0, self.M):
            s[i] = 0

        for i in range(0, self.N):
            q[i] = 0.0
            for j in range(0, self.M):
                s[j] = s[j] + r[i] * A[i][j]
                q[i] = q[i] + A[i][j] * p[j]

def kernel(self, A: list, C4: list, sum: list):
        for r in range(0, self.NR):
            for q in range(self.NQ):
                for p in range(0, self.NP):
                    sum[p] = 0.0
                    for s in range(self.NP):
                        sum[p] += A[r][q][s] * C4[s][p]

