def kernel(self, A: list):
        for i in range(0, self.N):
            # j < i
            for j in range(0, i):
                for k in range(0, j):
                    A[i][j] -= A[i][k] * A[j][k]
                A[i][j] /= A[j][j]

            # i == j case
            for k in range(0, i):
                A[i][i] -= A[i][k] * A[i][k]

            A[i][i] = math.sqrt(A[i][i])

def kernel(self, r: list, y: list):
        z = self.create_array(1, [self.N], self.DATA_TYPE(0))
        y[0] = -r[0]
        beta = 1.0
        alpha = -r[0]

        for k in range(1, self.N):
            beta = (1-alpha * alpha) * beta
            summ = 0.0

            for i in range(0, k):
                summ += r[k-i-1] * y[i]

            alpha = -(r[k] + summ) / beta

            for i in range(0, k):
                z[i] = y[i] + alpha * y[k-i-1]

            for i in range(0, k):
                y[i] = z[i]

            y[k] = alpha

def kernel(self, A: list, R: list, Q: list):
        for k in range(0, self.N):
            nrm = 0.0
            for i in range(0, self.M):
                nrm += A[i][k] * A[i][k]
            R[k][k] = math.sqrt(nrm)

            for i in range(0, self.M):
                Q[i][k] = A[i][k] / R[k][k]

            for j in range(k + 1, self.N):
                R[k][j] = 0.0
                for i in range(0, self.M):
                    R[k][j] += Q[i][k] * A[i][j]

                for i in range(0, self.M):
                    A[i][j] = A[i][j] - Q[i][k] * R[k][j]

def kernel(self, A: list):
        for i in range(0, self.N):
            for j in range(0, i):
                for k in range(0, j):
                    A[i][j] -= A[i][k] * A[k][j]
                A[i][j] /= A[j][j]

            for j in range(i, self.N):
                for k in range(0, i):
                    A[i][j] -= A[i][k] * A[k][j]

def kernel(self, A: list, b: list, x: list, y: list):
        for i in range(0, self.N):
            for j in range(0, i):
                w = A[i][j]
                for k in range(0, j):
                    w -= A[i][k] * A[k][j]
                A[i][j] = w / A[j][j]

            for j in range(i, self.N):
                w = A[i][j]
                for k in range(0, i):
                    w -= A[i][k] * A[k][j]
                A[i][j] = w

        for i in range(0, self.N):
            w = b[i]
            for j in range(0, i):
                w -= A[i][j] * y[j]
            y[i] = w

        for i in range(self.N - 1, -1, -1):
            w = y[i]
            for j in range(i + 1, self.N):
                w -= A[i][j] * x[j]
            x[i] = w / A[i][i]

def kernel(self, L: list, x: list, b: list):
        for i in range(0, self.N):
            x[i] = b[i]
            for j in range(0, i):
                x[i] -= L[i][j] * x[j]
            x[i] = x[i] / L[i][i]

def kernel(self, path: list):
